"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["7357"],{97101(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.municipio_sem_uf","status":422,"titulo":"O campo de munic\xedpio cita a UF respondida antes"},"descricao":{"codigo":"uniplus.item_formulario.municipio_sem_uf","requisitos":["UNI-REQ-0145"],"oQueAconteceu":["As op\xe7\xf5es do campo de munic\xedpio s\xe3o filtradas pela UF respondida antes (UNI-REQ-0145), e a restri\xe7\xe3o `MUNICIPIOS_DA_UF`, que cita o fato da UF, \xe9 obrigat\xf3ria no campo de tipo `MUNICIPIO`. O item enviado \xe9 de tipo `MUNICIPIO` e n\xe3o traz essa restri\xe7\xe3o. A mensagem \xe9 \\"O campo de munic\xedpio cita a UF respondida antes, pelos munic\xedpios da UF.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].restricoes` ou `grupos[g].subitens[j].restricoes`; nos modelos de formul\xe1rio come\xe7a por `conteudo.`. \xc9 uma entrada por item, junto das demais recusas da forma do item, e nada \xe9 gravado.","Na grava\xe7\xe3o dos itens do formul\xe1rio, esta recusa s\xf3 sai para o item cujo fato existe, \xe9 colet\xe1vel e combina com o tipo de campo: o item com fato [desconhecido](/erros/uniplus.item_formulario.fato_desconhecido), [n\xe3o colet\xe1vel](/erros/uniplus.item_formulario.fato_nao_coletavel) ou com tipo de campo [incoerente](/erros/uniplus.item_formulario.tipo_renderizacao_incoerente_com_dominio) \xe9 recusado por essa causa, e o resto da forma dele s\xf3 \xe9 conferido depois que ela for corrigida. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Acrescente ao item a restri\xe7\xe3o `MUNICIPIOS_DA_UF`, com o c\xf3digo do fato da UF em `fatos`. O fato da UF deve estar em um campo anterior do formul\xe1rio, de resposta \xfanica e com as UFs do Geo; caso contr\xe1rio, a recusa \xe9 a de [UF do munic\xedpio inv\xe1lida](/erros/uniplus.item_formulario.uf_do_municipio_invalida)."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);